inline MutationValues Record::into_values() && {
    auto r = memory_resource();
    MutationValues values(r);
    values.fields.emplace(String("id", r), generated_detail::encode(r, id_));
    values.fields.emplace(String("platform_id", r), generated_detail::encode(r, platform_id_));
    values.fields.emplace(String("class", r), generated_detail::encode(r, model_class_));
    values.fields.emplace(String("operator", r), generated_detail::encode(r, model_operator_));
    values.fields.emplace(String("template", r), generated_detail::encode(r, model_template_));
    values.fields.emplace(String("type", r), generated_detail::encode(r, type_));
    values.fields.emplace(String("match", r), generated_detail::encode(r, match_));
    values.fields.emplace(String("ordinary", r), generated_detail::encode(r, ordinary_));
    values.fields.emplace(String("namespace_id", r), generated_detail::encode(r, namespace_id_));
    values.fields.emplace(String("version", r), generated_detail::encode(r, version_));
    detail::EntityRuntimeAccess::retain_loaded_native_values(values, load_state);
    if (platform_) {
        values.fields.emplace(String("platform", r),
                              Value(r, std::move(*platform_).into_values().fields));
    }
    if (model_namespace_) {
        values.fields.emplace(String("model_namespace", r),
                              Value(r, std::move(*model_namespace_).into_values().fields));
    }
    inject_runtime(values);
    return values;
}

inline Record& Record::updatePlatform(const Platform& value) {
    platform_ = detail::make_box<Platform>(memory_resource(), value);
    updatePlatformId(value.id());
    return *this;
}

inline Record& Record::updateModelNamespace(const Platform& value) {
    model_namespace_ = detail::make_box<Platform>(memory_resource(), value);
    updateNamespaceId(value.id());
    return *this;
}
